<script setup lang="ts">
import AppIcon from '~/components/ui/AppIcon.vue'
type RefundInfo = { status: string; requestedAt: string; processedAt: string | null; decisionReason: string | null }
type Item = { id: string; paymentId: string | null; createdAt: string; type: string; item: string; chips: number | null; amountRub: number; status: string; refund: RefundInfo | null; refundEligibility: { code: string; eligible: boolean; message: string } }
const items = ref<Item[]>([]); const loading = ref(true); const error = ref(''); const refundTarget = ref<Item | null>(null); const refundReason = ref(''); const refundSubmitting = ref(false); const refundMessage = ref('')
async function loadHistory() { loading.value = true; error.value = ''; try { items.value = (await $fetch<{ items: Item[] }>('/api/payments/history')).items } catch { error.value = 'Не удалось загрузить историю покупок' } finally { loading.value = false } }
onMounted(loadHistory)
const typeLabel = (value: string) => value === 'PREMIUM' ? 'Premium' : 'Виртуальные фишки'
const statusLabel = (value: string) => ({ PENDING: 'Ожидается', SUCCEEDED: 'Оплачено', PROCESSED: 'Оплачено', CANCELED: 'Неуспешно' }[value] || value)
const refundStatusLabel = (value: string) => ({ REQUESTED: 'Возврат запрошен', APPROVED: 'Возврат одобрен', REFUNDED: 'Возвращено', REJECTED: 'Возврат отклонён' }[value] || value)
const statusClass = (value: string) => value.toLowerCase().replaceAll('_', '-')
function openRefund(item: Item) { refundTarget.value = item; refundReason.value = ''; refundMessage.value = '' }
function closeRefund() { if (!refundSubmitting.value) refundTarget.value = null }
async function submitRefund() { if (!refundTarget.value || refundSubmitting.value || refundReason.value.trim().length < 5) return; refundSubmitting.value = true; refundMessage.value = ''; try { await $fetch('/api/payments/refunds', { method: 'POST', body: { paymentId: refundTarget.value.id, reason: refundReason.value } }); refundTarget.value = null; await loadHistory() } catch (cause: any) { refundMessage.value = cause?.data?.message || cause?.data?.statusMessage || 'Не удалось отправить запрос' } finally { refundSubmitting.value = false } }
useHead({ title: 'История покупок · Poker Dealer Desk' })
</script>

<template>
  <main class="page-shell payment-history">
    <header class="history-hero"><div><p class="eyebrow">ПОКУПКИ И ПЛАТЕЖИ</p><h1>История операций</h1><p>Все покупки виртуальной валюты и Premium в одном месте. Статус отображается по серверным данным ЮKassa.</p></div><NuxtLink class="topup-link" to="/payments/virtual-currency">Пополнить фишки <AppIcon name="arrow-right" :size="16" /></NuxtLink></header>
    <p v-if="error" class="error panel">{{ error }}</p>
    <template v-if="!error">
    <section class="history-panel panel" aria-labelledby="history-title"><div class="panel-heading"><div><p class="eyebrow">АРХИВ</p><h2 id="history-title">Ваши покупки</h2></div><span v-if="!loading" class="count">{{ items.length }} {{ items.length === 1 ? 'операция' : 'операций' }}</span></div><div v-if="loading" class="empty-state">Загружаем операции…</div><div v-else-if="!items.length" class="empty-state"><span class="empty-icon" aria-hidden="true">◌</span><strong>Покупок пока нет</strong><p>После первой оплаты операция появится здесь.</p><NuxtLink class="topup-link" to="/payments/virtual-currency">Выбрать пакет фишек <AppIcon name="arrow-right" :size="16" /></NuxtLink></div><ul v-else class="history-list"><li v-for="item in items" :key="item.id" class="purchase-card"><div class="purchase-card__main"><div class="purchase-card__icon" :class="`purchase-card__icon--${item.type.toLowerCase()}`">{{ item.type === 'PREMIUM' ? '✦' : '◆' }}</div><div class="purchase-card__info"><div class="purchase-card__title"><strong>{{ typeLabel(item.type) }}</strong><span class="status" :class="`status--${statusClass(item.status)}`">{{ statusLabel(item.status) }}</span></div><h3>{{ item.item }}</h3><p>{{ item.chips ? `${item.chips.toLocaleString('ru-RU')} фишек` : 'Подписка на 30 дней' }} · {{ new Date(item.createdAt).toLocaleString('ru-RU') }}</p><span v-if="item.refund" class="refund-status" :class="`refund-status--${statusClass(item.refund.status)}`">{{ refundStatusLabel(item.refund.status) }}</span></div></div><div class="purchase-card__side"><strong>{{ item.amountRub.toLocaleString('ru-RU') }} ₽</strong><button v-if="item.refundEligibility.eligible" type="button" class="refund-button" @click="openRefund(item)">Запросить возврат</button><span v-else-if="item.refund" class="refund-hint">{{ item.refundEligibility.message }}</span></div><details class="purchase-details"><summary>Детали операции</summary><dl><div><dt>Тип</dt><dd>{{ typeLabel(item.type) }}</dd></div><div><dt>Статус возврата</dt><dd>{{ item.refund ? refundStatusLabel(item.refund.status) : item.refundEligibility.message }}</dd></div><div><dt>Payment ID</dt><dd>{{ item.paymentId || 'Появится после создания платежа' }}</dd></div></dl></details></li></ul></section>
    </template>
    <p class="history-note">Виртуальные фишки используются только внутри Pocker и не являются денежными средствами.</p>
  </main>
  <Teleport to="body"><div v-if="refundTarget" class="refund-backdrop" @click.self="closeRefund"><section class="refund-dialog" role="dialog" aria-modal="true" aria-labelledby="refund-title"><button class="dialog-close" type="button" aria-label="Закрыть" @click="closeRefund">×</button><p class="eyebrow">ЗАПРОС ВОЗВРАТА</p><h2 id="refund-title">{{ refundTarget.item }}</h2><p class="refund-summary">Сумма покупки: <strong>{{ refundTarget.amountRub.toLocaleString('ru-RU') }} ₽</strong></p><label class="reason-label" for="refund-reason">Причина возврата</label><textarea id="refund-reason" v-model="refundReason" rows="4" maxlength="1000" placeholder="Коротко опишите причину"></textarea><p class="dialog-hint">Запрос будет рассмотрен отдельно. Фактический возврат выполняется не этой формой.</p><p v-if="refundMessage" class="error-text">{{ refundMessage }}</p><div class="dialog-actions"><button type="button" class="secondary-button" :disabled="refundSubmitting" @click="closeRefund">Отмена</button><button type="button" class="primary-button" :disabled="refundSubmitting || refundReason.trim().length < 5" @click="submitRefund">{{ refundSubmitting ? 'Отправляем…' : 'Отправить запрос' }}</button></div></section></div></Teleport>
</template>

