-text-muted);font-size:1.7rem;cursor:pointer}.refund-dialog h2{margin:.35rem 0 .7rem}.refund-summary{color:var(--text-muted)}.refund-summary strong{color:var(--accent)}.reason-label{display:block;margin:1.15rem 0 .4rem;font-weight:700}.refund-dialog textarea{width:100%;resize:vertical;padding:.75rem;border:1px solid #ffffff20;border-radius:12px;background:#091a14;color:inherit;outline:none}.refund-dialog textarea:focus{border-color:var(--accent)}.dialog-hint{color:var(--text-muted);font-size:.75rem;line-height:1.45}.error-text{color:#ffaaa7;font-size:.8rem}.dialog-actions{display:flex;justify-content:flex-end;gap:.6rem;margin-top:1rem}.secondary-button,.primary-button{padding:.7rem 1rem;border:0;border-radius:11px;font-weight:800;cursor:pointer}.secondary-button{background:#ffffff12;color:inherit}.primary-button{background:var(--accent);color:#17251c}.secondary-button:disabled,.primary-button:disabled{opacity:.5;cursor:not-allowed}@media(max-width:650px){.history-hero{align-items:stretch;flex-direction:column;padding:1.1rem}.purchase-card{grid-template-columns:1fr}.purchase-card__side{text-align:left}.purchase-card__side>strong{font-size:1.1rem}.purchase-details dl div{align-items:flex-start;flex-direction:column;gap:.1rem}.purchase-details dd{max-width:100%;text-align:left}.dialog-actions{display:grid;grid-template-columns:1fr 1fr}.dialog-actions button{width:100%}}
